// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _value);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdraw(_value) { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        assertTrue(reverted || balBefore >= _value && balAfter == balBefore - _value);
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable {}
}
